import XCTest

class BookClubMessageTest: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
        Thread.sleep(forTimeInterval: 2)
    }

    func testOpenBookClubAndSendMessage() throws {
        // Dismiss any dialogs that might be showing
        let cancelButtons = app.buttons.matching(NSPredicate(format: "label == 'Cancel'"))
        if cancelButtons.count > 0 {
            cancelButtons.element(boundBy: 0).tap()
            Thread.sleep(forTimeInterval: 1)
        }

        // Look for Book Club room in the chat list
        let bookClubLabel = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH 'Book Club'")).element(boundBy: 0)

        if bookClubLabel.exists {
            print("✓ Found Book Club room")

            // Tap on the Book Club room
            if bookClubLabel.isHittable {
                bookClubLabel.tap()
                Thread.sleep(forTimeInterval: 2)
                print("✓ Opened Book Club room")

                // Find the message input field
                let messageField = app.textFields.firstMatch
                if messageField.exists && messageField.isHittable {
                    messageField.tap()
                    Thread.sleep(forTimeInterval: 0.5)

                    // Type the message
                    messageField.typeText("great read")
                    print("✓ Typed message: 'great read'")

                    // Find and tap the send button
                    let sendButton = app.buttons.matching(NSPredicate(format: "label CONTAINS[c] 'send'")).firstMatch
                    if sendButton.exists && sendButton.isHittable {
                        sendButton.tap()
                        Thread.sleep(forTimeInterval: 1)
                        print("✓ Sent message")
                    } else {
                        // Try pressing return if send button not found
                        app.keys["Return"].tap()
                        Thread.sleep(forTimeInterval: 1)
                        print("✓ Sent message via return key")
                    }

                    // Take screenshot to verify
                    let screenshot = XCUIScreen.main.screenshot()
                    print("✓ Room screen captured after sending message")
                } else {
                    XCTFail("Message input field not found")
                }
            }
        } else {
            XCTFail("Book Club room not found in chat list")
        }
    }
}

