import XCTest

final class SendHiBobTests: XCTestCase {
    func testSendHiBob() throws {
        continueAfterFailure = true
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        for _ in 0..<3 {
            for label in ["Cancel", "Not now", "Skip", "Dismiss", "No Thanks", "Later"] {
                let b = app.buttons[label]
                if b.exists && b.isHittable { b.tap(); Thread.sleep(forTimeInterval: 1) }
            }
            if app.staticTexts["All chats"].exists { break }
            let back = app.navigationBars.buttons.firstMatch
            if back.exists && back.isHittable { back.tap(); Thread.sleep(forTimeInterval: 1) }
        }

        let bobLabel = app.staticTexts.matching(NSPredicate(format: "label == 'Bob'")).element(boundBy: 0)
        XCTAssertTrue(bobLabel.waitForExistence(timeout: 30), "chat list did not show Bob")
        Thread.sleep(forTimeInterval: 2)
        bobLabel.tap()
        Thread.sleep(forTimeInterval: 3)

        var composer = app.textFields.firstMatch
        if !composer.exists {
            composer = app.textViews.firstMatch
        }
        XCTAssertTrue(composer.waitForExistence(timeout: 20), "composer not found")
        composer.tap()
        Thread.sleep(forTimeInterval: 1)
        composer.typeText("hi bob")
        Thread.sleep(forTimeInterval: 1)

        var send = app.buttons["sendButton"]
        if !send.exists {
            send = app.buttons.matching(NSPredicate(format: "label CONTAINS[c] 'send' OR identifier CONTAINS[c] 'send'")).firstMatch
        }
        if send.waitForExistence(timeout: 5), send.isHittable {
            send.tap()
            print("MARKER tapped send button")
        } else {
            app.keys["Return"].tap()
            print("MARKER tapped return key")
        }
        Thread.sleep(forTimeInterval: 3)

        let sent = app.staticTexts["hi bob"].waitForExistence(timeout: 15)
        if !sent {
            print("HIERARCHY-BEGIN")
            print(app.debugDescription)
            print("HIERARCHY-END")
        }
        XCTAssertTrue(sent, "message not visible in timeline")
    }
}

